{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table ttk_db.maplemonk.affiliate_fact_items as select traffic.date, sessions, addtocarts, checkouts, orders, round(revenue,2) revenue, cancelled_orders, round(cancelled_revenue,2) cancelled_revenue, round(realized_revenue,2) realized_revenue, round(earnings,2) earnings from ( select to_date(date, \'yyyymmdd\') date, sum(sessions) sessions, sum(addtocarts) addtocarts, sum(checkouts) checkouts from ttk_db.Maplemonk.GA4_GA4_Lovedepot_SESSIONS_USERS_BY_DATE where lower(sessionsourcemedium) like \'%icw %\' group by 1 order by 1 ) traffic left join (select order_timestamp::Date ordeR_Date, count(distinct ordeR_id) orders, sum(total_sales) revenue, count(distinct case when lower(ordeR_Status) like \'%cancelled%\' then ordeR_id end) cancelled_orders, sum(case when lower(ordeR_Status) like \'%cancelled%\' then total_Sales end) cancelled_Revenue, ifnull(revenue,0) - ifnull(cancelled_revenue,0) as realized_revenue, sum(earnings) earnings, from ( select ordeR_timestamp,order_id, coalesce(b.final_Status, a.ordeR_status) ordeR_Status, sum(total_sales) total_sales, sum(a.total_sales - b.tax) total_sales_before_tax, case when lower(coalesce(b.final_Status, a.ordeR_status)) not like \'%cancelled%\' and sum(total_sales) > 4000 then 0.15*sum(total_Sales) when lower(coalesce(b.final_Status, a.ordeR_status)) not like \'%cancelled%\' and sum(a.total_sales - b.tax) < 4000 then 0.2*sum(a.total_sales - b.tax) end as earnings from (select * from ttk_db.Maplemonk.ttk_db_SHOPIFY_FACT_ITEMS where shop_name = \'Shopify_love_depot_india\' and (lower(discount_codes) like \'%icw10%\' or upper(discount_codes) like \'%DDLOVE12%\' or upper(discount_codes) like \'%CKLOVE12%\' or upper(discount_codes) like \'%CMLOVE12%\' or upper(discount_codes) like \'%GRLOVE12%\' or upper(discount_codes) like \'%MRCLOVE12%\' or upper(discount_codes) like \'%SVLOVE12%\' or upper(discount_codes) like \'%INRLOVE12%\' or upper(discount_codes) like \'%PWLOVE12%\' or upper(discount_codes) like \'%CDLOVE12%\' or upper(discount_codes) like \'%GPLOVE12%\' or upper(discount_codes) like \'%CZLOVE12%\' or upper(discount_codes) like \'%CGLOVE12%\' or upper(discount_codes) like \'%JCNLOVE12%\' or upper(discount_codes) like \'%UNILOVE12%\' or upper(discount_codes) like \'%BMBLOVE12%\' )) a left join ( select * from ( select reference_code, SALEORDERITEMCODE, final_status, gross_sales_before_tax, tax, row_number() over (partition by reference_code, SALEORDERITEMCODE order by 1 desc) rw from ttk_db.Maplemonk.ttk_db_sales_consolidated where marketplace = \'SHOPIFY_LOVE_DEPOT_INDIA\' ) where rw = 1 ) b on a.ordeR_name = b.reference_Code and a.line_item_id = b.SALEORDERITEMCODE group by 1,2,3 ) group by 1 ) orders on traffic.date = orders.ordeR_Date; create or replace table ttk_db.maplemonk.affiliate_summary as select ordeR_timestamp, order_id, ordeR_name, sku, product_name, coalesce(b.final_Status, a.ordeR_status) ordeR_Status, final_utm_source final_utm_medium, final_utm_channel, discount_codes, round(total_sales,2) total_sales from (select * from ttk_db.Maplemonk.ttk_db_SHOPIFY_FACT_ITEMS where shop_name = \'Shopify_love_depot_india\' and (lower(discount_codes) like \'%icw10%\' or upper(discount_codes) like \'%DDLOVE12%\' or upper(discount_codes) like \'%CKLOVE12%\' or upper(discount_codes) like \'%CMLOVE12%\' or upper(discount_codes) like \'%GRLOVE12%\' or upper(discount_codes) like \'%MRCLOVE12%\' or upper(discount_codes) like \'%SVLOVE12%\' or upper(discount_codes) like \'%INRLOVE12%\' or upper(discount_codes) like \'%PWLOVE12%\' or upper(discount_codes) like \'%CDLOVE12%\' or upper(discount_codes) like \'%GPLOVE12%\' or upper(discount_codes) like \'%CZLOVE12%\' or upper(discount_codes) like \'%CGLOVE12%\' or upper(discount_codes) like \'%JCNLOVE12%\' or upper(discount_codes) like \'%UNILOVE12%\' or upper(discount_codes) like \'%BMBLOVE12%\' )) a left join ( select * from ( select reference_code, SALEORDERITEMCODE, final_status, gross_sales_before_tax , row_number() over (partition by reference_code, SALEORDERITEMCODE order by 1 desc) rw from ttk_db.Maplemonk.ttk_db_sales_consolidated where marketplace = \'SHOPIFY_LOVE_DEPOT_INDIA\' ) where rw = 1 ) b on a.ordeR_name = b.reference_Code and a.line_item_id = b.SALEORDERITEMCODE ;",
                    "transaction": true
